{"record_type":"item","candidate_slot_id":"slot_c2723943e9953b69","item_id":"slot_c2723943e9953b69#1","text":"因为做6到8微米是常规产品，投资不想太大，加工费也低","semantic_type":"fact","statement_role":"evidence","speech_role":"statement","perspective":"source_explicit","speaker_ref":"spk_9cb1bda27365","polarity":"affirmed","value":null,"behavior_status":null,"temporal_frame":"contemporaneous","evidence_quote":"因为做6到8微米是常规产品，投资不想太大，加工费也低","unknown_fields":[]}
